project_dir <- find_root(getwd()); helper_dir <- file.path(project_dir, ".codex", "study-mmrm-analysis", "R")
for (helper in c("canonical_hash.R", "standard_contract.R", "standard_analysis_definition.R", "analysis_plan.R", "analysis_contract_generation.R", "standard_sas.R", "io.R", "specification.R", "review_finalization.R", "analysis_approval.R")) source(file.path(helper_dir, helper), encoding = "UTF-8")
if (!requireNamespace("digest", quietly = TRUE) || !requireNamespace("yaml", quietly = TRUE)) stop("digest and yaml are required")
